const KEY='buy-or-bye-v5';const OLD='buy-or-bye-fancy-v1';const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}if(!state){let old;try{old=JSON.parse(localStorage.getItem(OLD))}catch{}state={cases:Array.isArray(old)&&old.length?old:SEED,users:[],userId:null,saved:[],myVotes:{},dupeVotes:{},quiz:null};}// Preserve real user posts while restoring missing demo cases after older-version migrations.
