function counts(c){const v=c.votes||[],buy=v.filter(x=>x.side==='buy').length;return{buy,bye:v.length-buy,pct:v.length?Math.round(buy/v.length*100):0}}function ownerOf(c){return c.ownerId?state.users.find(u=>u.id===c.ownerId)?.name||c.owner:c.owner||'Anonymous'}function isMine(c){return !!user()&&c.ownerId===state.userId}function voteKey(c){return (state.userId||'guest')+':'+c.id}function hasVoted(c){return !!user()&&!!state.myVotes[voteKey(c)]}function img(c){return c.image?`<img src="${esc(c.image)}" alt="${esc(c.title)}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('photo-unavailable')">`:`<span class="photo-placeholder">Photo coming soon</span>`}function price(n){return '$'+Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2})}if(state.users.length===1){for(const [k,v] of Object.entries(state.myVotes)){if(/^\d+$/.test(k)){state.myVotes[state.users[0].id+':'+k]=v;delete state.myVotes[k]}}}function updateNav(){$('avatarText').textContent=user()?.name?.slice(0,1).toUpperCase()||'↗'}function filteredCases(){let arr=state.cases.filter(c=>(audience==='All'||(audience==='Following'&&isFollowingAuthor(c))||(audience==='Saved'&&state.saved.some(id=>String(id)===String(c.id))))&&(category==='All'||c.category===category)&&(`${c.title} ${c.desc}`.toLowerCase().includes(query)));if(sort==='popular')arr.sort((a,b)=>(b.votes?.length||0)-(a.votes?.length||0));if(sort==='low')arr.sort((a,b)=>a.price-b.price);if(sort==='high')arr.sort((a,b)=>b.price-a.price);if(sort==='new')arr.sort((a,b)=>b.id-a.id);return arr}
