let exploreQuery='',exploreCategory='All',exploreSort='new';function renderExplore(){const target=$('exploreCards');if(!target)return;let arr=state.cases.filter(c=>(exploreCategory==='All'||c.category===exploreCategory)&&(`${c.title} ${c.desc}`.toLowerCase().includes(exploreQuery)));if(exploreSort==='popular')arr.sort((a,b)=>(b.votes?.length||0)-(a.votes?.length||0));if(exploreSort==='low')arr.sort((a,b)=>a.price-b.price);if(exploreSort==='high')arr.sort((a,b)=>b.price-a.price);if(exploreSort==='new')arr.sort((a,b)=>b.id-a.id);$('exploreFilters').innerHTML=cats.map(c=>`<button class="chip ${exploreCategory===c?'active':''}" data-xfilter="${c}">${c}</button>`).join('');target.innerHTML=arr.length?arr.map(caseCard).join(''):'<div class="empty">No matching dilemmas.</div>';document.querySelectorAll('[data-xfilter]').forEach(b=>b.onclick=()=>{exploreCategory=b.dataset.xfilter;renderExplore()});wireCards(target)}
function modal(title,body){document.querySelectorAll('.case-header-nav,.case-side-nav').forEach(n=>n.remove());$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('overlay').classList.add('show');document.body.style.overflow='hidden';$('overlay').querySelector('.dialog').scrollTop=0}function close(){mySpaceReturnTab=null;if(window._photoObject){URL.revokeObjectURL(window._photoObject);window._photoObject=null}$('overlay').classList.remove('show');document.body.style.overflow=''}$('closeModal').onclick=close;$('overlay').onclick=e=>{if(e.target===$('overlay'))close()};document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});function ensureLogin(next){if(user())return true;login(next);return false}
let loginReturn='profile',guestSwipes=[],swipePromptShown=false;
