function onboarding(next='profile'){loginReturn=next;modal('WELCOME IN',`<div class="onboard-hero"><div class="onboard-symbol">✦</div><div class="eyebrow">YOU'RE IN</div><h2>How do you want to explore?</h2><p class="muted">New around here? Take the mini tour. Already know your way? Jump right in.</p></div><div class="onboard-choices"><button class="onboard-choice" id="chooseTour"><span class="choice-icon">🧭</span><strong>Walk me through</strong><small>A quick tour of posting, swiping, and your profile.</small></button><button class="onboard-choice" id="chooseFast"><span class="choice-icon">⚡</span><strong>I already know</strong><small>Skip the introduction and start exploring.</small></button></div><div style="text-align:center"><button class="onboard-skip" id="skipTour">Skip for now →</button></div>`);$('chooseTour').onclick=()=>tourStep(0,next);$('chooseFast').onclick=()=>finishOnboard(next);$('skipTour').onclick=()=>finishOnboard(next)}
const TOUR=[['📸','Post a dilemma','Add a photo, your price, and why you’re undecided.'],['↔️','Swipe BUY or BYE','Judge other people’s purchases. Your votes are saved when you’re signed in.'],['💬','Unlock the conversation','Vote to see what the jury thinks and read their comments.'],['👤','Your profile, your call','Your own posts live in My profile. Only you can mark them bought or skipped.']];
