function finishOnboard(next){if(next==='vote'&&nextCase){const id=Number(nextCase);nextCase=null;return openCase(id)}if(next==='create')return create();if(next==='swipe')return showSwipe();if(next==='vote'&&nextCase)return openCase(Number(nextCase));if(next==='swipevote')return commitPendingSwipe();profile()}
