function mySpaceBackMarkup(){return mySpaceReturnTab!==null?'<button class="btn soft small myspace-return" id="returnToMySpace">← Back to My Space</button>':''}
function wireMySpaceBack(){const btn=$('returnToMySpace');if(btn)btn.onclick=()=>profile(mySpaceReturnTab||'posts')}
function publicProfile(id,name){const u=state.users.find(u=>u.id===id);const display=u?.name||name||'Community member';const mine=state.cases.filter(c=>id?c.ownerId===id:!c.ownerId&&c.owner===name);modal('PUBLIC PROFILE',`${mySpaceBackMarkup()}<button class="btn soft small profile-back" id="publicBack">← ${user()&&id===user().id?'Back to My profile':'Back to discover'}</button><div class="profile-head"><div class="avatar">${esc(display[0]?.toUpperCase()||'?')}</div><div><h2>${esc(display)}</h2><div class="tiny">Community profile · ${mine.length} public posts</div></div>${!(user()&&id===user().id)?`<button class="btn follow-btn ${myFollowedAuthors().includes(authorKey(id,name))?'following':''}" id="publicFollow">${myFollowedAuthors().includes(authorKey(id,name))?'✓ Following':'+ Follow creator'}</button>`:''}</div><p class="muted">Public posts and community opinions. Private purchase decisions are not displayed here.</p><div class="history">${mine.length?mine.map(c=>`<div class="history-row"><div class="thumb" style="background:${esc(c.bg||'#eee')}">${img(c)}</div><div class="details"><strong>${esc(c.title)}</strong><small>${price(c.price)} · ${c.votes?.length||0} votes</small></div><button class="btn soft small" data-open="${c.id}">View →</button></div>`).join(''):'<div class="empty">No public posts yet.</div>'}</div>`);document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openCase(Number(b.dataset.open)));wireMySpaceBack();if($('publicFollow'))$('publicFollow').onclick=()=>toggleAuthorFollow(id,name);$('publicBack').onclick=()=>{if(mySpaceReturnTab!==null)profile(mySpaceReturnTab);else if(user()&&id===user().id)profile();else{close();showHome()}}}
function caseNavigator(id,manage){
 const cases=state.cases.slice().sort((a,b)=>b.id-a.id);
 const at=cases.findIndex(c=>c.id===id);
 if(at<0)return;
 const prev=cases[at-1],next=cases[at+1];
 const counter=document.createElement('span');counter.className='case-header-nav';counter.setAttribute('aria-label','Dilemma position');counter.textContent=(at+1)+' / '+cases.length;
 $('modalTitle').after(counter);
 const rail=document.createElement('div');rail.className='case-side-nav';rail.setAttribute('aria-label','Browse shopping dilemmas');
 const make=(item,arrow,label,side)=>{const b=document.createElement('button');b.type='button';b.className='case-nav-btn case-side-'+side;b.innerHTML=side==='left'?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14.5 5l-7 7 7 7"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.5 5l7 7-7 7"/></svg>';b.title=label;b.setAttribute('aria-label',label);b.disabled=!item;if(item)b.onclick=()=>openCase(item.id,manage&&isMine(item));return b};
 rail.append(make(prev,'‹','Previous dilemma','left'),make(next,'›','Next dilemma','right'));
 $('overlay').appendChild(rail);
}
function openCase(id,manage=false){const c=state.cases.find(c=>c.id===id);if(!c)return;selectedSide=null;const mine=isMine(c)&&manage,voted=hasVoted(c),s=counts(c);const reveal=voted||mine;modal(c.title,`${mySpaceBackMarkup()}<div class="case-detail"><div><div class="photo" style="background:${esc(c.bg||'#eee8fa')}">${img(c)}</div><div style="margin-top:18px" class="eyebrow">${esc(c.category)}</div><h2>${esc(c.title)}</h2><div class="case-price">${price(c.price)}</div><p class="muted">${esc(c.desc)}</p><div class="creator-actions"><button class="btn soft small" id="ownerLink">By ${esc(ownerOf(c))} ↗</button>${!isMine(c)?`<button class="btn follow-btn ${isFollowingAuthor(c)?'following':''}" id="followAuthor">${isFollowingAuthor(c)?'✓ Following creator':'+ Follow creator'}</button>`:''}</div>${c.budget?`<div class="budget-stats"><div><span>MONTHLY BUDGET</span><strong>${price(c.budget)}</strong></div><div><span>ITEM / BUDGET</span><strong>${Math.round(c.price/c.budget*100)}%</strong></div></div>`:''}<div class="sub-actions"><button class="btn soft small" id="saveCase">${state.saved.includes(c.id)?'♥ Saved':'♡ Save post'}</button><button class="btn soft small" id="shareCase">↗ Share result</button>${mine&&c.image?'<button class="btn soft small" id="removeCasePhoto">Remove photo</button>':''}</div></div><div><div class="eyebrow">THE PEOPLE VS. THE PURCHASE</div><h2 style="font-size:30px">${mine?'Your case, your call.':'What’s your verdict?'}</h2>${mine?`<p class="muted">You own this post. The final decision lives here in your private view.</p><div class="vote-panel"><strong>Your final decision</strong><p class="muted">${c.decision?'Current choice: '+(c.decision==='buy'?'I bought it':'I skipped it'):'Still deciding? You can update this later.'}</p><div class="choice-row"><button class="btn mint" id="decideBuy">I bought it</button><button class="btn pink" id="decideBye">I skipped it</button></div></div>`:isMine(c)?`<p class="muted">This is your post. Manage your final decision from My profile.</p><button class="btn soft small" id="goManage">Manage my post →</button>`:voted?`<div class="notice">✓ You voted ${state.myVotes[voteKey(c)].toUpperCase()}. Thanks for helping!</div>`:`<p class="muted">Vote first. See everyone else's opinions after.</p><div class="choice-row"><button class="btn mint" id="chooseBuy">♡ BUY IT</button><button class="btn pink" id="chooseBye">✕ BYE BYE</button></div><div class="field"><label>YOUR REASON <span class="optional-tag">OPTIONAL · YOU CAN LEAVE THIS BLANK</span></label><textarea class="textarea" id="voteReason" maxlength="350" placeholder="Make your case…"></textarea></div><div class="sub-actions"><button class="btn primary" id="submitVote" disabled>Submit verdict →</button></div>`}<div id="resultsBlock">${reveal?resultHTML(c,s):'<div class="notice">🔒 Blind vote: results unlock after your vote.</div>'}</div>${mine||!isMine(c)?`<div class="ai-advisor ai-entry"><span class="eyebrow">✦ POWERED BY AI</span><h3>${isMine(c)?"Your AI Shopping Advisor":"Need a second opinion?"}</h3><p class="muted">Understand why to buy or skip, and explore smarter alternatives.</p><button class="btn primary small" id="openAiAdvisor">✦ ${isMine(c)?"View AI analysis":"Ask AI"} →</button></div>`:''}<div class="sub-actions">${reveal?'<button class="btn soft small" id="dupeBtn">+ Suggest a dupe</button>':''}${c.dupes?.length&&reveal?'<button class="btn soft small" id="battleBtn">Compare alternatives →</button>':''}</div></div></div>`);caseNavigator(id,manage);wireMySpaceBack();$('ownerLink').onclick=()=>publicProfile(c.ownerId,c.owner);if($('followAuthor'))$('followAuthor').onclick=()=>toggleAuthorFollow(c.ownerId,c.owner,c.id);$('saveCase').onclick=()=>{if(!ensureLogin('profile'))return;state.saved=state.saved.includes(c.id)?state.saved.filter(x=>x!==c.id):[...state.saved,c.id];persist();const dialog=$('overlay').querySelector('.dialog');const oldScroll=dialog?.scrollTop||0;openCase(id,manage);if(dialog)dialog.scrollTop=oldScroll;toast(state.saved.includes(c.id)?'Saved':'Removed from saved')};$('shareCase').onclick=()=>share(c);if($('goManage'))$('goManage').onclick=()=>openCase(c.id,true);if(mine){$('decideBuy').onclick=()=>decide(c,'buy');$('decideBye').onclick=()=>decide(c,'bye');if($('removeCasePhoto'))$('removeCasePhoto').onclick=()=>{if(!confirm('Remove this photo from your post?'))return;c.image='';persist();openCase(id)}}else if(!voted&&!isMine(c)){$('chooseBuy').onclick=()=>pickSide('buy');$('chooseBye').onclick=()=>pickSide('bye');$('submitVote').onclick=()=>submitVote(c);void 0}if($('openAiAdvisor'))$('openAiAdvisor').onclick=()=>openAiAdvisor(c,manage);if($('dupeBtn'))$('dupeBtn').onclick=()=>dupeForm(c);if($('battleBtn'))$('battleBtn').onclick=()=>battle(c)}function pickSide(s){selectedSide=s;$('chooseBuy').style.boxShadow=s==='buy'?'inset 0 0 0 2px #7fc5a0':'';$('chooseBye').style.boxShadow=s==='bye'?'inset 0 0 0 2px #ee93ae':'';$('submitVote').disabled=false}function submitVote(c,skip=false){if(!selectedSide)return;const reason=skip?'':$('voteReason').value.trim();if(!ensureLogin('vote')){nextCase=c.id;return}if(state.myVotes[c.id])return toast('You already voted');c.votes??=[];c.votes.push({side:selectedSide,reason,author:user().name,authorId:user().id});state.myVotes[voteKey(c)]=selectedSide;persist();openCase(c.id);toast('Verdict recorded!')}function resultHTML(c,s){return `<div class="vote-panel"><div class="split-title"><strong>The jury says</strong><span class="badge">${c.votes?.length||0} votes</span></div><h3 style="font:700 28px 'Space Grotesk';margin:10px 0 0">${s.pct}% BUY <span style="font-size:15px;color:#aaa">/</span> ${100-s.pct}% BYE</h3><div class="vote-meter"><span style="width:${s.pct}%"></span></div>${(c.votes||[]).slice(-5).reverse().map(v=>`<div class="reason"><span class="badge" style="background:${v.side==='buy'?'#e4f5e9':'#ffebf0'}">${v.side==='buy'?'BUY':'BYE'}</span> ${v.reason?esc(v.reason):'<em style="color:#999">No reason added</em>'}<small>— ${esc(v.author||'Anonymous')}</small></div>`).join('')||'<p class="muted">No votes yet.</p>'}</div>`}function decide(c,side){if(!isMine(c))return toast('Only the owner can decide');c.decision=side;persist();openCase(c.id,true);toast('Your decision is saved privately')}function share(c){const s=counts(c);const txt=`BUY OR BYE? ${c.title} · ${price(c.price)} · ${s.pct}% BUY / ${100-s.pct}% BYE`;modal('SHARE THE VERDICT',`<div style="background:#eee9fb;border-radius:20px;padding:35px;text-align:center"><div class="eyebrow">THE COURT HAS SPOKEN</div><h2 style="font:700 34px 'Space Grotesk'">${esc(c.title)}</h2><h3 style="font:700 44px 'Space Grotesk';color:var(--purple)">${s.pct}% BUY</h3><p>${c.votes?.length||0} community votes</p></div><p class="muted">Copy the result as text. This offline demo does not generate a public link.</p><button class="btn primary" id="copyShare">Copy verdict →</button>`);$('copyShare').onclick=()=>copy(txt)}async function copy(t){try{await navigator.clipboard.writeText(t);toast('Copied!')}catch{toast('Clipboard unavailable in this browser')}}
function create(){if(!ensureLogin('create'))return;photoData='';photoFile=null;photoBusy=false;modal('POST A DILEMMA',`<div class="eyebrow">PUT IT ON TRIAL</div><h2 style="font:700 31px 'Space Grotesk';letter-spacing:-1px">What's in your cart?</h2><form id="createForm"><div class="form-grid"><div class="field"><label>ITEM NAME *</label><input class="input" name="title" maxlength="70" required placeholder="The $300 cup"></div><div class="field"><label>PRICE (USD) *</label><input class="input" type="number" name="price" min=".01" max="1000000" step=".01" required placeholder="300"></div><div class="field"><label>CATEGORY</label><select class="select" name="category">${cats.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>MONTHLY SPENDING BUDGET (OPTIONAL)</label><input class="input" type="number" name="budget" min="0" step=".01" placeholder="600"></div></div><div class="field"><label>WHY ARE YOU TORN? *</label><textarea class="textarea" name="desc" required maxlength="400" placeholder="I want it so badly, but…"></textarea></div><div class="field"><label>PRODUCT PHOTO</label><div class="upload" id="dropZone"><input type="file" id="photoInput" accept="image/*,.heic,.heif,.avif,.bmp,.gif"><label for="photoInput">📷 Click to choose a photo, drag one here, or paste a screenshot</label><div class="upload-status" id="uploadStatus">JPG · PNG · WebP · GIF · AVIF · BMP · supported HEIC/HEIF · max 20 MB</div><div id="previewBox" hidden><img id="photoPreview" alt="Upload preview"><div style="margin-top:10px"><button class="btn soft small" type="button" id="removePhoto">Remove photo ×</button></div></div></div></div><p class="tiny">Images are compressed in your browser. HEIC support depends on your browser.</p><button type="submit" class="btn primary" id="publishBtn">Publish case →</button></form>`);const input=$('photoInput'),drop=$('dropZone');async function process(file){if(!file)return;if(!file.type.startsWith('image/')&&!/\.(heic|heif|avif|bmp|gif)$/i.test(file.name))return toast('Choose an image file');if(file.size>20*1024*1024)return toast('Maximum image size is 20 MB');photoBusy=true;$('uploadStatus').textContent='Processing '+file.name+'…';try{const result=await compress(file);photoData=result;photoFile=file;$('photoPreview').src=result;$('previewBox').hidden=false;$('uploadStatus').textContent='✓ '+file.name+' ready'}catch(e){photoData='';photoFile=null;$('previewBox').hidden=true;$('uploadStatus').textContent='Could not read image. Try JPG or PNG.';toast('This browser cannot decode that image format')}finally{photoBusy=false}}input.onchange=()=>process(input.files[0]);$('removePhoto').onclick=()=>{photoData='';photoFile=null;input.value='';$('photoPreview').removeAttribute('src');$('previewBox').hidden=true;$('uploadStatus').textContent='No photo selected'};drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');process(e.dataTransfer.files[0])};const paste=e=>{if(!$('createForm')){document.removeEventListener('paste',paste);return}const f=[...(e.clipboardData?.files||[])][0]||[...(e.clipboardData?.items||[])].find(i=>i.type.startsWith('image/'))?.getAsFile();if(f){e.preventDefault();process(f)}};document.addEventListener('paste',paste);$('createForm').onsubmit=e=>{e.preventDefault();if(photoBusy)return toast('Wait for the photo to finish processing');const fd=new FormData(e.target),p=Number(fd.get('price'));if(!p||p<=0)return;const c={id:Date.now(),title:String(fd.get('title')).trim(),price:p,category:fd.get('category'),budget:Number(fd.get('budget'))||null,desc:String(fd.get('desc')).trim(),owner:user().name,ownerId:user().id,emoji:'🛍️',bg:'#f0e9ff',image:photoData,votes:[],dupes:[]};state.cases.unshift(c);if(!persist()){state.cases.shift();return}close();audience='All';category='All';query='';sort='new';$('search').value='';$('sort').value='new';render();window.scrollTo({top:0,behavior:'smooth'});toast('✓ Published! Your dilemma is now live.')}}
function compress(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{try{const max=1100,scale=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight)),w=Math.max(1,Math.round(im.naturalWidth*scale)),h=Math.max(1,Math.round(im.naturalHeight*scale));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.drawImage(im,0,0,w,h);const data=canvas.toDataURL('image/jpeg',.77);URL.revokeObjectURL(url);resolve(data)}catch(e){URL.revokeObjectURL(url);reject(e)}};im.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('decode'))};im.src=url})}
let pendingSwipe=null;
function startSwipe(){swipeList=state.cases.filter(c=>!isMine(c)&&!hasVoted(c));swipeIndex=0;if(!user()&&!swipePromptShown){swipePromptShown=true;return swipeGuestPrompt()}showSwipe()}
function swipeGuestPrompt(){modal('BEFORE YOU SWIPE',`<div class="guest-notice"><div class="onboard-symbol">↔️</div><div class="eyebrow">SWIPE MODE</div><h2>Swipe freely. Remember everything.</h2><p>Want to revisit your swipe history or read what others think about an item? Sign in to save your verdicts and unlock the comments.</p><div class="hero-actions"><button class="btn primary" id="guestSignIn">Sign in →</button><button class="btn soft" id="guestContinue">Continue as guest</button></div></div><p class="tiny" style="text-align:center">Guest swipes are only temporary and won’t appear in your history.</p>`);$('guestSignIn').onclick=()=>login('swipe');$('guestContinue').onclick=showSwipe}
function commitPendingSwipe(){if(!pendingSwipe)return showSwipe();const {id,side,reason}=pendingSwipe;const c=state.cases.find(x=>x.id===id);if(c&&!hasVoted(c)){c.votes??=[];c.votes.push({side,reason,author:user().name,authorId:user().id});state.myVotes[voteKey(c)]=side;persist()}pendingSwipe=null;swipeIndex++;render();showSwipe()}
function showSwipe(){if(swipeIndex>=swipeList.length){modal('SWIPE MODE',`<div class="swipe-stage"><h2 style="font:700 35px 'Space Grotesk'">All caught up ✨</h2><p class="muted">You've judged every available case. Check back when someone posts a new dilemma.</p><button class="btn primary" id="swipeBrowse">Explore cases →</button></div>`);$('swipeBrowse').onclick=()=>{close();$('discover').scrollIntoView({behavior:'smooth'})};return}const c=swipeList[swipeIndex];modal('SWIPE MODE · '+(swipeIndex+1)+' / '+swipeList.length,`<div class="swipe-stage"><div class="eyebrow">LEFT = BYE · RIGHT = BUY</div><div class="swipe-card" id="swipeCard"><div class="swipe-photo" style="background:${esc(c.bg||'#eee')}">${img(c)}</div><div class="swipe-info"><div class="swipe-meta"><span>${esc(c.category)}</span><strong>${price(c.price)}</strong></div><h3>${esc(c.title)}</h3><p>${esc(c.desc)}</p></div></div><div class="swipe-actions"><button class="btn pink" id="swipeBye">← BYE</button><button class="btn mint" id="swipeBuy">BUY →</button></div><div class="tiny">Drag the card or use ← → on your keyboard</div></div>`);$('swipeBye').onclick=()=>swipeReason('bye');$('swipeBuy').onclick=()=>swipeReason('buy');let startX=0;const card=$('swipeCard');card.onpointerdown=e=>{startX=e.clientX;card.setPointerCapture(e.pointerId)};card.onpointerup=e=>{const delta=e.clientX-startX;if(Math.abs(delta)>65)swipeReason(delta>0?'buy':'bye')}}function swipeReason(side){const c=swipeList[swipeIndex];modal('YOUR VERDICT',`<div class="swipe-stage"><div class="eyebrow">${side==='buy'?'♡ BUY IT':'✕ BYE BYE'}</div><h2 style="font:700 29px 'Space Grotesk'">Why ${side==='buy'?'buy':'skip'} ${esc(c.title)}?</h2><label class="swipe-reason-label" for="swipeReasonText">YOUR REASON <span class="optional-tag">OPTIONAL · YOU CAN LEAVE THIS BLANK</span></label><textarea class="textarea swipe-reason-input" id="swipeReasonText" placeholder="Add a reason if you like — no explanation needed to vote." maxlength="350"></textarea><div class="swipe-actions"><button class="btn soft" id="swipeBack">Back</button><button class="btn primary" id="swipeSubmit">Submit & next →</button></div></div>`);$('swipeBack').onclick=showSwipe;$('swipeSubmit').onclick=()=>{const reason=$('swipeReasonText').value.trim();if(!user()){guestSwipes.push({id:c.id,side,reason});swipeIndex++;return guestSwipeAfterVote(c)}if(!hasVoted(c)){c.votes??=[];c.votes.push({side,reason,author:user().name,authorId:user().id});state.myVotes[voteKey(c)]=side;persist()}swipeIndex++;render();showSwipe()}}document.addEventListener('keydown',e=>{if(!$('swipeCard')||['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='ArrowLeft')swipeReason('bye');if(e.key==='ArrowRight')swipeReason('buy')});
function guestSwipeAfterVote(c){modal('VERDICT CAST',`<div class="guest-notice"><div class="onboard-symbol">✨</div><h2>Nice call!</h2><p>Sign in to save your swipe history and unlock the jury comments. Or keep swiping as a guest.</p><div class="hero-actions"><button class="btn primary" id="guestSaveVotes">Sign in & save →</button><button class="btn soft" id="guestPrevious">← Go back</button><button class="btn soft" id="guestNext">Next swipe →</button></div></div>`);$('guestSaveVotes').onclick=()=>{pendingSwipe=guestSwipes[guestSwipes.length-1];swipeIndex=Math.max(0,swipeIndex-1);login('swipevote')};$('guestPrevious').onclick=()=>{swipeIndex=Math.max(0,swipeIndex-1);guestSwipes.pop();showSwipe()};$('guestNext').onclick=showSwipe}
function dupeForm(c){if(!ensureLogin('profile'))return;modal('SUGGEST A DUPE',`<div class="eyebrow">BETTER FOR LESS?</div><h2 style="font:700 28px 'Space Grotesk'">Challenge ${esc(c.title)}</h2><form id="dupeForm"><div class="field"><label>ALTERNATIVE ITEM</label><input class="input" name="title" required maxlength="70" placeholder="A similar cup for less"></div><div class="field"><label>PRICE (USD)</label><input class="input" name="price" required type="number" min=".01" step=".01"></div><div class="field"><label>WHY IS IT BETTER?</label><textarea class="textarea" name="reason" maxlength="250" placeholder="Same quality, lower price…"></textarea></div><div class="field"><label>OPTIONAL PHOTO</label><input class="input" type="file" id="dupePhoto" accept="image/*,.heic,.heif"></div><button class="btn primary" type="submit">Start battle →</button></form>`);$('dupeForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);let photo='';const f=$('dupePhoto').files[0];if(f){try{photo=await compress(f)}catch{return toast('Cannot read image; try JPG or PNG')}}const d={id:Date.now(),title:String(fd.get('title')).trim(),price:Number(fd.get('price')),reason:String(fd.get('reason')).trim(),image:photo,votes:{original:0,dupe:0,neither:0}};c.dupes??=[];c.dupes.push(d);persist();battle(c);toast('Dupe challenge added!')}}function battle(c){const d=c.dupes?.[0];if(!d)return dupeForm(c);const v=d.votes||{original:0,dupe:0,neither:0};modal('DUPE BATTLE',`<div class="eyebrow">ORIGINAL VS ALTERNATIVE</div><h2 style="font:700 30px 'Space Grotesk'">Which one wins?</h2><div class="dupe-grid"><div class="dupe-tile"><div class="dupe-img" style="background:${esc(c.bg||'#eee')}">${img(c)}</div><strong>${esc(c.title)}</strong><span>${price(c.price)}</span></div><div class="dupe-tile"><div class="dupe-img" style="background:#f0e9ff">${d.image?`<img src="${d.image}" alt="Dupe">`:'🛍️'}</div><strong>${esc(d.title)}</strong><span>${price(d.price)}</span></div></div><p class="muted">${esc(d.reason)}</p><div class="notice">Price difference: ${price(Math.abs(c.price-d.price))}</div><div class="sub-actions"><button class="btn soft small" data-battle="original">Original</button><button class="btn mint small" data-battle="dupe">The dupe</button><button class="btn pink small" data-battle="neither">Neither</button></div><p class="tiny">${v.original} original · ${v.dupe} dupe · ${v.neither} neither</p><button class="btn soft small" id="battleBack">← Back to case</button>`);document.querySelectorAll('[data-battle]').forEach(b=>b.onclick=()=>{if(!ensureLogin('profile'))return;const k=c.id+'-'+d.id;if(state.dupeVotes[k])return toast('You already voted in this battle');d.votes[b.dataset.battle]++;state.dupeVotes[k]=b.dataset.battle;persist();battle(c)});$('battleBack').onclick=()=>openCase(c.id)}
const QUIZ=[{q:'A product catches your eye. What matters most?',a:['How it makes me feel','How long it lasts','Whether it saves money','The experience it creates']},{q:'Your friends say it is expensive. You…',a:['Still love it','Check the quality','Compare alternatives','Think about the memories']},{q:'Your ideal shopping win is…',a:['A unique find','A durable staple','A smart bargain','An unforgettable outing']},{q:'Your wishlist is full of…',a:['Statement pieces','Timeless essentials','Practical upgrades','Trips and tickets']}];const TYPES=['The Trend Lover ✨','The Quality Keeper 🧵','The Smart Saver 🌱','The Memory Maker 🎟️'];let quizAnswers=[];function quizStart(){quizAnswers=[];quizStep(0)}function quizStep(i){if(i===QUIZ.length){const n=[0,0,0,0];quizAnswers.forEach(x=>n[x]++);const type=TYPES[n.indexOf(Math.max(...n))];state.quiz=type;persist();modal('SHOPPING DNA',`<div class="swipe-stage" style="padding:30px;background:#eee9fc;border-radius:18px"><div class="eyebrow">YOUR SHOPPING PERSONALITY</div><h2 style="font:700 35px 'Space Grotesk'">${type}</h2><p class="muted">A playful quiz based on your answers, not an AI assessment.</p><button class="btn primary" id="quizRestart">Try again →</button></div>`);$('quizRestart').onclick=quizStart;return}const q=QUIZ[i];modal('SHOPPING DNA · '+(i+1)+' / '+QUIZ.length,`<div class="eyebrow">A LITTLE SELF-DISCOVERY</div><h2 style="font:700 27px 'Space Grotesk'">${q.q}</h2>${q.a.map((a,j)=>`<button class="quiz-opt" data-quiz="${j}">${esc(a)}</button>`).join('')}${i>0?'<button class="btn soft small" id="quizBack" style="margin-top:14px">← Previous question</button>':''}`);if(i>0)$('quizBack').onclick=()=>{quizAnswers.pop();quizStep(i-1)};document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{quizAnswers.push(Number(b.dataset.quiz));quizStep(i+1)})}function labRecords(){state.regretRecords=state.regretRecords||{};const id=user()?.id;if(!id)return [];state.regretRecords[id]=state.regretRecords[id]||[];return state.regretRecords[id]}
function labFormatDate(t){return new Date(t).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function labDays(r){return Math.max(0,Math.ceil((r.until-Date.now())/86400000))}
function labItem(r){const days=labDays(r),elapsed=Math.min(100,Math.max(0,(Date.now()-r.started)/(7*86400000)*100)),finished=!!r.decision;const label=finished?(r.decision==='bought'?'Bought it':'Skipped it'):(days?'Day '+Math.min(7,Math.floor((Date.now()-r.started)/86400000)+1)+' of 7':'Ready to decide');return `<div class="lab-item">${r.image?`<div class="lab-photo"><img src="${esc(r.image)}" alt="${esc(r.title)}" loading="lazy"></div>`:``}<div class="lab-item-head"><div><h3>${esc(r.title)}</h3><p>${price(r.price)} · ${r.source==='post'?'From your post':'Private wishlist'} · Started ${labFormatDate(r.started)}</p></div><span class="lab-pill">${esc(label)}</span></div><div class="lab-progress"><span style="width:${finished?100:elapsed}%"></span></div><p>${finished?`Your decision: ${r.decision==='bought'?'Bought it':'Skipped it'} on ${labFormatDate(r.decidedAt||Date.now())}`:days?`${days} day${days===1?'':'s'} remaining · Check back ${labFormatDate(r.until)}`:'Your 7-day pause is complete. Ready to make the call?'}</p>${r.note?`<p style="color:#625777">“${esc(r.note)}”</p>`:''}<div class="lab-actions">${!finished?`<button class="btn primary small" data-lab-decide="${esc(r.id)}" data-decision="bought">I bought it</button><button class="btn soft small" data-lab-decide="${esc(r.id)}" data-decision="skipped">I skipped it</button>`:`<button class="btn soft small" data-lab-reopen="${esc(r.id)}">Reconsider</button>`}<button class="btn soft small" data-lab-delete="${esc(r.id)}">Remove</button></div></div>`}
function regretLab(){if(!ensureLogin('profile'))return;const records=labRecords();const active=records.filter(r=>!r.decision),skipped=records.filter(r=>r.decision==='skipped');const avoided=skipped.reduce((sum,r)=>sum+Number(r.price||0),0);const mine=state.cases.filter(c=>isMine(c)&&!records.some(r=>r.source==='post'&&r.caseId===c.id));modal('REGRET LAB',`<div class="eyebrow">YOUR PRIVATE SHOPPING PAUSE</div><h2 style="font:700 clamp(27px,4vw,36px) 'Space Grotesk';margin:8px 0">Want it next week, too?</h2><p class="muted">Save an item, wait seven days, then decide. No public post required.</p><div class="lab-summary"><div class="lab-stat"><strong>${active.length}</strong><small>Cooling off</small></div><div class="lab-stat"><strong>${skipped.length}</strong><small>Skipped</small></div><div class="lab-stat"><strong>${price(avoided)}</strong><small>Potential spend avoided</small></div></div><div class="lab-note">Private to this demo account and browser. “Potential spend avoided” is the total price of items you marked skipped—not actual savings.</div><div class="sub-actions" style="margin:20px 0"><button class="btn primary" id="labAdd">+ Add a private item</button>${mine.length?'<button class="btn soft" id="labFromPost">Add from my posts</button>':''}</div>${records.length?records.slice().sort((a,b)=>(!!a.decision)-(!!b.decision)||b.started-a.started).map(labItem).join(''):'<div class="lab-empty"><strong>Your wishlist starts here.</strong><p class="muted">Add something you are thinking about buying. We’ll help you pause before deciding.</p></div>'}<div class="sub-actions"><button class="btn soft small" id="labDone">← Back to browsing</button></div>`);$('labAdd').onclick=labAddPrivate;if($('labFromPost'))$('labFromPost').onclick=()=>labFromPost(mine);$('labDone').onclick=close;document.querySelectorAll('[data-lab-decide]').forEach(b=>b.onclick=()=>labDecide(b.dataset.labDecide,b.dataset.decision));document.querySelectorAll('[data-lab-reopen]').forEach(b=>b.onclick=()=>{const r=labRecords().find(x=>x.id===b.dataset.labReopen);if(r){delete r.decision;delete r.decidedAt;persist();regretLab()}});document.querySelectorAll('[data-lab-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Remove this item from your private Regret Lab?'))return;const arr=labRecords(),i=arr.findIndex(x=>x.id===b.dataset.labDelete);if(i>=0){arr.splice(i,1);persist();regretLab()}})}
function labAddPrivate(){modal('ADD TO REGRET LAB',`<div class="eyebrow">PRIVATE WISHLIST</div><h2 style="font:700 29px 'Space Grotesk'">Sleep on it.</h2><p class="muted">Your item stays private. The 7-day timer starts when you save.</p><form id="labPrivateForm"><div class="field"><label>ITEM PHOTO (OPTIONAL)</label><div class="lab-upload" id="labDrop"><input type="file" id="labPhoto" accept="image/*,.heic,.heif,.webp,.avif,.png,.jpg,.jpeg,.gif" hidden><button class="btn soft" type="button" id="labChoose">＋ Choose photo</button><span class="tiny">JPG, PNG, WebP, GIF, HEIC* · max 12 MB</span><div id="labPhotoPreview"></div></div></div><div class="field"><label>WHAT ARE YOU THINKING OF BUYING?</label><input class="input" name="title" required maxlength="90" placeholder="e.g. The $300 dream cup"></div><div class="field"><label>PRICE (USD)</label><input class="input" name="price" required type="number" min="0" step="0.01" placeholder="300"></div><div class="field"><label>WHY DO YOU WANT IT? (OPTIONAL)</label><textarea class="textarea" name="note" maxlength="240" placeholder="A little note to your future self..."></textarea></div><div class="sub-actions"><button class="btn soft" type="button" id="labFormBack">← Back</button><button class="btn primary" type="submit">Start my 7-day pause →</button></div></form>`);$('labFormBack').onclick=regretLab;let labPhotoData='';const labInput=$('labPhoto'),labPreview=$('labPhotoPreview'),labChoose=$('labChoose');labChoose.onclick=()=>labInput.click();function labUpdatePreview(){labPreview.innerHTML=labPhotoData?`<div class="lab-preview"><img src="${labPhotoData}" alt="Photo preview"><button class="btn soft small" type="button" id="labRemovePhoto">Remove photo</button></div>`:'';if($('labRemovePhoto'))$('labRemovePhoto').onclick=()=>{labPhotoData='';labInput.value='';labUpdatePreview()}}labInput.onchange=async()=>{const file=labInput.files?.[0];if(!file)return;if(file.size>12*1024*1024){toast('Please choose an image under 12 MB');labInput.value='';return}labChoose.disabled=true;labChoose.textContent='Processing photo…';try{labPhotoData=await compress(file);labUpdatePreview()}catch{toast('This photo format could not be opened. Try JPG or PNG.')}finally{labChoose.disabled=false;labChoose.textContent='＋ Choose photo'}};const labDrop=$('labDrop');labDrop.ondragover=e=>{e.preventDefault();labDrop.classList.add('drag')};labDrop.ondragleave=()=>labDrop.classList.remove('drag');labDrop.ondrop=async e=>{e.preventDefault();labDrop.classList.remove('drag');const f=e.dataTransfer.files[0];if(!f)return;if(f.size>12*1024*1024)return toast('Please choose an image under 12 MB');try{labPhotoData=await compress(f);labUpdatePreview()}catch{toast('Could not read this image')}};$('labPrivateForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')).trim(),p=Number(f.get('price'));if(!title||!Number.isFinite(p)||p<0)return toast('Enter a valid item and price');const now=Date.now();labRecords().push({id:'r'+now+Math.random().toString(36).slice(2,7),title,price:p,image:labPhotoData,note:String(f.get('note')||'').trim(),source:'private',started:now,until:now+7*86400000});persist();regretLab();toast('Your private countdown has started!')}}
function labFromPost(mine){modal('ADD FROM MY POSTS',`<div class="eyebrow">YOUR PURCHASE DILEMMAS</div><h2 style="font:700 29px 'Space Grotesk'">Pick one to pause.</h2><div class="history">${mine.map(c=>`<div class="history-row">${c.image?`<div class="thumb"><img src="${esc(c.image)}" alt=""></div>`:''}<div class="details"><strong>${esc(c.title)}</strong><small>${price(c.price)}</small></div><button class="btn primary small" data-lab-post="${c.id}">Start 7 days</button></div>`).join('')}</div><div class="sub-actions"><button class="btn soft" id="labPostBack">← Back</button></div>`);$('labPostBack').onclick=regretLab;document.querySelectorAll('[data-lab-post]').forEach(b=>b.onclick=()=>{const c=state.cases.find(x=>x.id===Number(b.dataset.labPost));if(!c||!isMine(c))return;const now=Date.now();labRecords().push({id:'r'+now+Math.random().toString(36).slice(2,7),caseId:c.id,title:c.title,price:c.price,image:c.image||'',source:'post',started:now,until:now+7*86400000});persist();regretLab();toast('Countdown started!')})}
function labDecide(id,decision){const r=labRecords().find(x=>x.id===id);if(!r)return;r.decision=decision;r.decidedAt=Date.now();persist();regretLab();toast(decision==='bought'?'Decision recorded: bought it':'Decision recorded: skipped it')}
