if((()=>{try{return !sessionStorage.getItem('bob-welcome-v9')}catch{return true}})()){try{sessionStorage.setItem('bob-welcome-v9','1')}catch{};const tip=document.createElement('div');tip.className='welcome-tip welcome-tip-xl';tip.innerHTML='<button class="tip-x" aria-label="Dismiss tip">×</button><strong>👋 First time here?</strong><span>See how to post, swipe and get opinions in 30 seconds.</span><button class="btn primary small" id="tipHow">Show me how →</button>';document.body.appendChild(tip);tip.querySelector('.tip-x').onclick=()=>tip.remove();tip.querySelector('#tipHow').onclick=()=>{tip.remove();showGuide()}}

function setupStyledSorts(ids=['sort','exploreSort']){
  ids.forEach(id=>{
    const select=document.getElementById(id);
    if(!select||select.parentElement.classList.contains('sort-shell'))return;
    const shell=document.createElement('div');shell.className='sort-shell';
    select.parentNode.insertBefore(shell,select);shell.appendChild(select);
    const trigger=document.createElement('button');trigger.type='button';trigger.className='sort-trigger';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
    const menu=document.createElement('div');menu.className='sort-menu';menu.hidden=true;menu.setAttribute('role','listbox');
    function sync(){trigger.innerHTML='<span>'+select.options[select.selectedIndex].textContent+'</span><span class="sort-chevron"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></span>';menu.innerHTML='';[...select.options].forEach(opt=>{const b=document.createElement('button');b.type='button';b.textContent=opt.textContent;b.setAttribute('role','option');b.setAttribute('aria-selected',String(select.value===opt.value));b.onclick=()=>{select.value=opt.value;select.dispatchEvent(new Event('change',{bubbles:true}));sync();closeMenu()};menu.appendChild(b)})}
    function closeMenu(){menu.hidden=true;trigger.setAttribute('aria-expanded','false')}
    trigger.onclick=e=>{e.stopPropagation();const opening=menu.hidden;document.querySelectorAll('.sort-menu').forEach(m=>m.hidden=true);document.querySelectorAll('.sort-trigger').forEach(b=>b.setAttribute('aria-expanded','false'));menu.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening))};
    shell.append(trigger,menu);sync();select.addEventListener('change',sync);
    document.addEventListener('click',e=>{if(!shell.contains(e.target))closeMenu()});
    trigger.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
  });
}
setupStyledSorts();

// Owner-only AI advice. The backend holds the Gemini key; never embed it in frontend code.
function aiCacheKey(c){return 'buyorbye_ai_'+String(c.id)}
function loadAiCache(c){try{return JSON.parse(localStorage.getItem(aiCacheKey(c))||'null')}catch{return null}}
function openAiAdvisor(c,manage=false){
 modal('AI SHOPPING ADVISOR',`${mySpaceBackMarkup()}<div class="ai-full-view"><div class="ai-topline"><button class="btn soft small" id="aiGoBack">← Go back to dilemma</button><span class="eyebrow">✦ GEMINI-POWERED INSIGHTS</span></div><h2>Should you buy ${esc(c.title)}?</h2><p class="muted">A balanced look at the community's arguments and possible alternatives.</p><div class="ai-controls"><label for="aiMode">WHAT WOULD YOU LIKE TO SEE?</label><select class="select" id="aiMode"><option value="all">Full AI analysis</option><option value="jury">Why buy vs. why skip</option><option value="alternatives">Smart alternatives</option></select><button class="btn primary" id="runAiAdvisor">✦ ${loadAiCache(c)?'Refresh analysis':'Generate analysis'}</button></div><div id="aiAdvisorOutput" class="ai-placeholder">Select an option and generate an AI analysis.</div><p class="tiny">AI-generated suggestions are not verified listings, live prices or financial advice.</p></div>`);
 wireMySpaceBack();$('aiGoBack').onclick=()=>openCase(c.id,manage);
 $('runAiAdvisor').onclick=()=>runAiAdvisor(c);
 $('aiMode').onchange=()=>{const cached=loadAiCache(c);if(cached)renderAiAdvisor(cached)};
 setupStyledSorts(['aiMode']);
 const cached=loadAiCache(c);if(cached)renderAiAdvisor(cached);
}
function renderAiAdvisor(a){const root=document.getElementById('aiAdvisorOutput');if(!root||!a)return;
 const mode=document.getElementById('aiMode')?.value||'all';
 const list=(items)=>Array.isArray(items)&&items.length?'<ul>'+items.map(x=>'<li>'+esc(String(x))+'</li>').join('')+'</ul>':'<p class="muted">Not enough information yet.</p>';
 const alternatives=Array.isArray(a.alternatives)?a.alternatives:[];
 const jury=`<section class="ai-jury-block"><div class="eyebrow">01 / THE JURY, EXPLAINED</div><div class="ai-reasons"><article class="ai-section"><h4>♡ Why Buy?</h4>${list(a.why_buy)}</article><article class="ai-section"><h4>✕ Why Skip?</h4>${list(a.why_skip)}</article></div><p class="tiny">${esc(a.vote_context||'')} · Community opinions are not proof of affordability.</p></section>`;
 const alts=`<section class="ai-alternatives-block"><div class="eyebrow">02 / SMART ALTERNATIVES</div><h3>Other ways to get what you want</h3><div class="ai-alt-list">${alternatives.length?alternatives.map(x=>`<article class="ai-alt"><div class="ai-alt-heading"><strong>${esc(x.name||'Alternative')}</strong>${x.estimated_price_usd!=null?`<span class="ai-price">~$${esc(String(x.estimated_price_usd))}</span>`:''}</div><p>${esc(x.why||'')}</p>${x.tradeoff?`<small>Trade-off: ${esc(x.tradeoff)}</small>`:''}</article>`).join(''):'<p class="muted">No alternatives yet.</p>'}</div><p class="tiny">Estimated prices are not verified live offers.</p></section>`;
 const conclusion=`<section class="ai-final-block"><div class="eyebrow">03 / FINAL AI RECOMMENDATION</div><p>${esc(a.recommendation||'')}</p></section>`;
 root.innerHTML=`<div class="ai-report">${mode!=='alternatives'?jury:''}${mode!=='jury'?alts:''}${conclusion}</div>`;
}
async function runAiAdvisor(c){const btn=document.getElementById('runAiAdvisor'),out=document.getElementById('aiAdvisorOutput');if(!btn||!out)return;btn.disabled=true;btn.textContent='Analyzing…';out.textContent='Reading the jury votes, comments and suggested dupes…';
 try{const r=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:c.title,price:c.price,category:c.category,description:c.desc,budget:c.budget||null,votes:(c.votes||[]).map(v=>({side:v.side,reason:v.reason||''})),dupes:(c.dupes||[]).map(d=>({name:d.title,price:d.price,reason:d.reason||''}))})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'AI service unavailable');localStorage.setItem(aiCacheKey(c),JSON.stringify(data));renderAiAdvisor(data)}catch(e){out.innerHTML='<div class="notice">'+esc(String(e.message||e))+'. Start the Python server and configure GEMINI_API_KEY to enable real AI analysis.</div>'}finally{btn.disabled=false;btn.textContent='✦ Refresh analysis'}}

